        /// <summary>
        /// Unregisters <param cref="instance" /> and unregisters all input action callbacks via <see cref="ActorActions.UnregisterCallbacks(IActorActions)" />.
        /// </summary>
        /// <seealso cref="ActorActions.UnregisterCallbacks(IActorActions)" />
        public void RemoveCallbacks(IActorActions instance)
        {
            if (m_Wrapper.m_ActorActionsCallbackInterfaces.Remove(instance))
                UnregisterCallbacks(instance);
        }

        /// <summary>
        /// Replaces all existing callback instances and previously registered input action callbacks associated with them with callbacks provided via <param cref="instance" />.
        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="ActorActions.AddCallbacks(IActorActions)" />
        /// <seealso cref="ActorActions.RemoveCallbacks(IActorActions)" />
        /// <seealso cref="ActorActions.UnregisterCallbacks(IActorActions)" />
        public void SetCallbacks(IActorActions instance)
        {
            foreach (var item in m_Wrapper.m_ActorActionsCallbackInterfaces)
                UnregisterCallbacks(item);
            m_Wrapper.m_ActorActionsCallbackInterfaces.Clear();
            AddCallbacks(instance);
        }
